interface Repo {
  fun add(item: Item)
  fun addAll(items: List<Item>)
}

class DbRepo : Repo {
  override fun add(item: Item) { /* insert */ }
  override fun addAll(items: List<Item>) { items.forEach { add(it) } }   // self-call
}

// Broken: addAll never logs. The generated forwarder calls inner.addAll,
// and inner's self-call reaches DbRepo.add, not the override below.
class LoggingRepo(private val inner: Repo) : Repo by inner {
  override fun add(item: Item) {
    log("add $item")
    inner.add(item)
  }
}

// Correct: every entry point you care about is overridden
class LoggingRepo2(private val inner: Repo) : Repo by inner {
  override fun add(item: Item) {
    log("add $item")
    inner.add(item)
  }
  override fun addAll(items: List<Item>) {
    log("addAll ${items.size}")
    inner.addAll(items)
  }
}

