class Setting<T>(private val default: T) : ReadWriteProperty<Any?, T> {
  private var cached: T? = null                        // state lives in the DELEGATE
  override fun getValue(thisRef: Any?, property: KProperty<*>): T = cached ?: default
  override fun setValue(thisRef: Any?, property: KProperty<*>, value: T) { cached = value }
}

// Broken: one object, two properties, one shared value
class BadPrefs {
  private val shared = Setting("")
  var theme: String by shared
  var locale: String by shared                         // writing theme changes locale
}

// Correct: one delegate object per property
class Prefs {
  var theme: String by Setting("system")
  var locale: String by Setting("en")
}

// The property is handed in — derive the key from it, not from delegate state
class PrefKey(
  private val prefs: SharedPreferences,
  private val default: String,
) : ReadWriteProperty<Any?, String> {
  override fun getValue(thisRef: Any?, property: KProperty<*>): String =
    prefs.getString(property.name, default) ?: default
  override fun setValue(thisRef: Any?, property: KProperty<*>, value: String) {
    prefs.edit().putString(property.name, value).apply()
  }
}

// provideDelegate — runs once, when the property is created
class Required(private val prefs: SharedPreferences) {
  operator fun provideDelegate(
    thisRef: Any?,
    property: KProperty<*>,
  ): ReadWriteProperty<Any?, String> {
    require(prefs.contains(property.name)) { "missing preference ${property.name}" }
    return PrefKey(prefs, "")
  }
}

